// OpenSSL-signed phars (SHA-1 / SHA-256 / SHA-512 over RSA) verified against
// <phar>.pubkey; a missing or wrong public key makes the phar unloadable.
$dir = sys_get_temp_dir() . '/rhp_golden_phar_openssl_' . getmypid();
@mkdir($dir);
$other = "-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEb0juCnk6R2lIWkq0bSWzPBsoImrB\nO4bihc90FOdq4LXCZ3weD9YelPP4XpA8W+gswhpe+pBkgCqdPqTf8vN72g==\n-----END PUBLIC KEY-----\n";
foreach ($PHARS as $n => $b64) {
    $f = "$dir/sig_$n.phar";
    file_put_contents($f, base64_decode($b64));
    file_put_contents("$f.pubkey", $PUB);
    $p = Phar::loadPhar($f, "sig_$n.phar");
    echo $n, ": ", var_export($p, true), "\n";
    echo file_get_contents("phar://$f/hello.php"), "\n";
}
foreach (['missing' => null, 'wrong' => $other, 'garbage' => "not a key", 'cert' => $CERT] as $case => $key) {
    $f = "$dir/bad_$case.phar";
    file_put_contents($f, base64_decode($PHARS['sha256']));
    if ($key !== null) file_put_contents("$f.pubkey", $key);
    try {
        var_dump(Phar::loadPhar($f, "bad_$case.phar"));
        echo "$case: loaded\n";
    } catch (Exception $e) {
        echo get_class($e), " ";
        echo "$case: ", preg_replace('~"[^"]*/~', '"', $e->getMessage()), "\n";
    }
    @unlink("$f.pubkey");
    @unlink($f);
}
foreach ($PHARS as $n => $b64) { @unlink("$dir/sig_$n.phar.pubkey"); @unlink("$dir/sig_$n.phar"); }
@rmdir($dir);
